/**
 * Reusable modal dialog for Modern Commerce React surfaces.
 *
 * Exposes two things:
 *  - {@link Modal}: a presentational, portalled modal component (header/body/footer)
 *    for declarative use inside any component.
 *  - {@link confirmDialog}: an imperative `Promise<boolean>` confirmation helper that
 *    replaces blocking `window.confirm()` calls. Resolves true on confirm, false on
 *    cancel/dismiss.
 *
 * @module     local_moderncommerce/modal
 * @copyright  2025 Adebare Showemimo | adebareshowemimo@gmail.com | support@agunfoninteractivity.com | www.agunfoninteractivity.com
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
/**
 * Framework-free form validation rules for Modern Commerce.
 *
 * Every rule is a plain function returning the error message when the value is
 * invalid, or undefined when it is fine. Messages are always supplied by the
 * caller from its own `labels` prop — this module never contains user-facing
 * English, so it stays translatable.
 *
 * @module     local_moderncommerce/validation
 * @copyright  2025 Adebare Showemimo | adebareshowemimo@gmail.com | support@agunfoninteractivity.com | www.agunfoninteractivity.com
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
/**
 * Shared form primitives for Modern Commerce React surfaces.
 *
 * Wraps a control in the mc-* field vocabulary and wires the accessibility
 * contract in one place: the required asterisk stays aria-hidden while the
 * control carries aria-required, the inline message is associated through
 * aria-describedby, and aria-invalid is present only while an error is showing.
 *
 * Pair with useFormValidation to get validate-on-submit, revalidate-on-change
 * and focus-the-first-error behaviour without per-field wiring.
 *
 * @module     local_moderncommerce/form
 * @copyright  2025 Adebare Showemimo | adebareshowemimo@gmail.com | support@agunfoninteractivity.com | www.agunfoninteractivity.com
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
